(()=>{'use strict';const $=s=>document.querySelector(s);function boot(){if($('#l3MomoFab'))return;const b=document.createElement('button');b.id='l3MomoFab';b.className='l3-momo-fab';b.type='button';b.setAttribute('aria-label','Momo');b.innerHTML='🐶<span>Momo</span>';b.onclick=()=>window.CCNERLevel3?.openMomo?.();document.body.appendChild(b);const g=$('#gameView');if(g)new MutationObserver(()=>{b.hidden=!g.hidden}).observe(g,{attributes:true,attributeFilter:['hidden']})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot()})();